class Masa:
    def __init__(self, masa_no):
        self.masa_no = masa_no
        self.dolu_mu = False
        self.hesap = 0.0

    def siparis_ekle(self, tutar):
        self.hesap += tutar
        self.dolu_mu = True
        print(f'Masa {self.masa_no} güncel hesap: {self.hesap:.2f} TL')

class Savasci:
    def __init__(self, isim, can=100):
        self.isim = isim
        self.can = can

    def hasar_al(self, miktar):
        self.can -= miktar
        if self.can <= 0:
            self.can = 0
            print(f'💀 {self.isim} elendi!')
        else:
            print(f'⚔️ {self.isim} hasar aldı! Kalan can: {self.can}')

class Kitap:
    def __init__(self, baslik, toplam_sayfa):
        self.baslik = baslik
        self.toplam_sayfa = toplam_sayfa
        self.okunan_sayfa = 0

    def sayfa_oku(self, sayfa):
        self.okunan_sayfa += sayfa
        print(f'{self.baslik}: {self.okunan_sayfa}/{self.toplam_sayfa} sayfa okundu.')

class Kart:
    def __init__(self, sahip, limit=500):
        self.sahip = sahip
        self.limit = limit

    def harca(self, tutar):
        if tutar <= self.limit:
            self.limit -= tutar
            print(f'Onaylandı. Kalan limit: {self.limit} TL')
        else:
            print('Yetersiz limit!')

