class Karakter:
    def __init__(self, isim, guc):
        self.isim = isim
        self.can = 100
        self.guc = guc

    def saldir(self, hedef):
        print(f'{self.isim}, {hedef.isim} karakterine saldırdı!')
        hedef.can -= self.guc
        print(f'{hedef.isim} kalan can: {hedef.can}')
